WITH product_stats AS (SELECT product_id, COUNT(DISTINCT revenue) AS unique_products, COUNT(revenue) AS revenue_count FROM store_sales GROUP BY product_id) SELECT products.id, products.product_name, products.cost, product_stats.unique_products, product_stats.revenue_count FROM products JOIN product_stats ON products.id = product_stats.product_id WHERE product_stats.unique_products >= 4 ORDER BY unique_products DESC;
